const withModel = entry => ({ ...entry, ...(entry.modelAvailable ? getTokenMonsterModelProfile(entry.cardId) : {}) });
export const TOKEN_MONSTER_PROFILES = deepFreeze(nativeRows.map(withModel));
export const NATIVE_TOKEN_RECORDS = deepFreeze([...TOKEN_MONSTER_PROFILES, ...placeholders]);
export const PRINTED_TOKEN_PRESENTATIONS = deepFreeze(printedRows.map(withModel));
export const COMMEMORATIVE_TOKEN_PRESENTATIONS = deepFreeze(commemorativeRows);
